/-- `Erased α` is the same as `α`, except that the elements
  of `Erased α` are erased in the VM in the same way as types
  and proofs. This can be used to track data without storing it
  literally. -/
def Erased (α : Sort u) : Sort max 1 u :=
  { s : α → Prop // ∃ a, (a = ·) = s }

/-- Promote `HahnEmbedding.Partial.evalCoeff`'s output to a new `HahnSeries`. -/
noncomputable
def eval [IsOrderedAddMonoid R] [Archimedean R] (x : M) :
    Lex R⟦FiniteArchimedeanClass M⟧ :=
  toLex { coeff := f.evalCoeff x
          isPWO_support' := (f.isWF_support_evalCoeff x).isPWO }

/-- The Euclidean Levi-Civita symbol `ε_{ijkl}` in dimension 4. -/
def _root_.euclidLeviCivita (g : Fin 4 → Fin 4) : ℝ :=
  generalizedKroneckerDelta g (id : Fin 4 → Fin 4)

